import{_ as a,o as t,c as n,ah as s}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse(`{"title":"Paramètres de l'application","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/parametres-application.md","filePath":"src/guide/admin/parametres-application.md"}`),r={name:"guide/admin/parametres-application.md"};function i(o,e,l,u,c,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="parametres-de-l-application" tabindex="-1">Paramètres de l&#39;application <a class="header-anchor" href="#parametres-de-l-application" aria-label="Permalink to &quot;Paramètres de l&#39;application&quot;">​</a></h1><p><strong>Paramètres de l&#39;application</strong>, dans l&#39;espace <strong>Administration</strong>, regroupe tout ce qui personnalise votre espace ERA : son identité visuelle, ce qui s&#39;imprime sur les reçus, et deux réglages qui changent réellement le comportement de l&#39;app pour les autres utilisateurs.</p><p>Ces réglages valent pour tout l&#39;établissement, pas pour votre compte. Pour vos préférences personnelles (thème, langue, sécurité), voir <a href="/era-guide/guide/prise-en-main.html">Bien démarrer</a>.</p><h2 id="identite" tabindex="-1">Identité <a class="header-anchor" href="#identite" aria-label="Permalink to &quot;Identité&quot;">​</a></h2><p>Le <strong>nom de l&#39;application</strong> remplace « ERA » partout dans l&#39;interface, dans les e-mails et sur les documents générés. C&#39;est ce qui permet à l&#39;établissement d&#39;afficher son propre nom plutôt que celui du logiciel.</p><h2 id="couleurs" tabindex="-1">Couleurs <a class="header-anchor" href="#couleurs" aria-label="Permalink to &quot;Couleurs&quot;">​</a></h2><p>Une <strong>couleur primaire</strong> et une <strong>couleur secondaire</strong>, appliquées à toute l&#39;interface. Le bouton <strong>Réinitialiser</strong> ramène aux valeurs par défaut d&#39;ERA si un essai ne convient pas — utile avant de chercher à corriger une teinte à la main.</p><h2 id="logo" tabindex="-1">Logo <a class="header-anchor" href="#logo" aria-label="Permalink to &quot;Logo&quot;">​</a></h2><p>Deux logos distincts, et la différence compte :</p><ul><li>Le <strong>logo complet</strong> s&#39;affiche sur la page d&#39;accueil et sur les pages de connexion. C&#39;est aussi celui qui apparaît sur les bulletins et les reçus de paiement des sites qui n&#39;ont pas de logo propre (voir <a href="/era-guide/guide/admin/structure-etablissement.html">Structure de l&#39;établissement</a>).</li><li>Le <strong>logo icône</strong> s&#39;affiche en haut de la colonne des espaces, sur fond bleu foncé. Si vous ne le renseignez pas, le logo complet est utilisé à sa place — ce qui donne souvent un résultat illisible une fois réduit. Prévoyez une version carrée, lisible sur fond sombre.</li></ul><h2 id="pages-de-connexion" tabindex="-1">Pages de connexion <a class="header-anchor" href="#pages-de-connexion" aria-label="Permalink to &quot;Pages de connexion&quot;">​</a></h2><p>La section <strong>Pages de connexion</strong> règle ce que voient les familles et le personnel avant de saisir quoi que ce soit.</p><ul><li><strong>Image de fond</strong> — une photo de l&#39;établissement, affichée derrière le panneau bleu foncé sur ordinateur, et en bandeau au-dessus du formulaire sur téléphone. Formats JPG, PNG ou WebP, 4 Mo au maximum. ERA la recouvre d&#39;un voile bleu pour que le texte reste lisible quelle que soit la photo. Sans image, le panneau reste uni. <strong>Supprimer</strong> la retire.</li><li><strong>Afficher le logo dans une pastille blanche</strong> — à activer si votre logo se confond avec le bleu foncé du cadre : il s&#39;affiche alors sur une petite tuile blanche, sur les pages de connexion comme dans l&#39;application. Ce réglage ne s&#39;applique qu&#39;à <strong>votre</strong> logo : celui d&#39;ERA est recoloré automatiquement et reste affiché nu.</li></ul><h2 id="accroche-d-accueil" tabindex="-1">Accroche d&#39;accueil <a class="header-anchor" href="#accroche-d-accueil" aria-label="Permalink to &quot;Accroche d&#39;accueil&quot;">​</a></h2><p>L&#39;accroche et le sous-titre de la page d&#39;accueil ne se modifient plus ici : ils ont rejoint le reste du contenu de la page, dans <a href="/era-guide/guide/admin/page-accueil.html">Page d&#39;accueil</a>.</p><h2 id="personnalisation-des-recus" tabindex="-1">Personnalisation des reçus <a class="header-anchor" href="#personnalisation-des-recus" aria-label="Permalink to &quot;Personnalisation des reçus&quot;">​</a></h2><p>Ces champs s&#39;impriment sur <strong>chaque reçu de paiement généré</strong>, en plus du logo (celui du site de l&#39;élève s&#39;il en a un, sinon le logo complet) : adresse, téléphone, e-mail, message de remerciement et note de bas de page. Ces champs sont communs à tous les sites.</p><p>C&#39;est ici qu&#39;on met les mentions que la famille doit retrouver sur son justificatif. Les reçus déjà générés ne sont pas réécrits : le changement s&#39;applique aux reçus produits ensuite.</p><h2 id="rattachement-libre-service-des-parents" tabindex="-1">Rattachement libre-service des parents <a class="header-anchor" href="#rattachement-libre-service-des-parents" aria-label="Permalink to &quot;Rattachement libre-service des parents&quot;">​</a></h2><p>Ce réglage décide si un parent peut <strong>rechercher un élève déjà inscrit et se rattacher lui-même</strong> à son dossier.</p><ul><li><strong>Activé</strong> : le parent effectue la démarche seul depuis son portail (voir <a href="/era-guide/guide/parent/enfants-et-documents.html">Mes enfants et leurs documents</a>).</li><li><strong>Désactivé</strong> : cette possibilité disparaît du portail parent. Le rattachement doit alors être fait par l&#39;administration, depuis le dossier de l&#39;élève (voir <a href="/era-guide/guide/admin/eleves-tuteurs.html">Élèves et tuteurs</a>).</li></ul><p>Vérifiez ce réglage avant de conclure qu&#39;un parent « ne trouve pas » la fonction : elle peut simplement être désactivée pour l&#39;établissement.</p><h2 id="notation" tabindex="-1">Notation <a class="header-anchor" href="#notation" aria-label="Permalink to &quot;Notation&quot;">​</a></h2><p>Ce réglage décide <strong>comment la moyenne d&#39;une matière combine les notes de différents types d&#39;évaluation</strong> (devoir, composition, interrogation…).</p><ul><li><strong>Désactivé</strong> (comportement par défaut) : chaque note pèse selon le poids de son type d&#39;évaluation, tel que défini dans <a href="/era-guide/guide/admin/structure-etablissement.html">Structure de l&#39;établissement</a>.</li><li><strong>Activé</strong> : chaque type d&#39;évaluation pèse autant, quel que soit le nombre de notes qu&#39;il contient. Trois interrogations ne pèsent alors pas plus lourd qu&#39;une composition unique.</li></ul><p>C&#39;est un choix pédagogique, pas un détail d&#39;affichage : il change les moyennes calculées, donc les bulletins. Arrêtez-le avant la première publication de bulletins de l&#39;année, et évitez d&#39;en changer en cours d&#39;année.</p>',26)])])}const g=a(r,[["render",i]]);export{m as __pageData,g as default};
